.roadview-overlay
{
	position: absolute;
	top: 0;
	bottom: 0;
	left: 0;
	right: auto;
	width: min(66vw, calc(100% - 360px));
	min-width: min(520px, 100%);
	max-width: 100%;
	z-index: 260;
	overflow: hidden;
	pointer-events: none;
	opacity: 0;
	transform: translateX(-24px) scale(1.02);
	transition: opacity 0.28s ease, transform 0.32s ease;
	background: #000;
}

.roadview-overlay.detail-panel-roadview
{
	position: fixed;
	top: 0;
	right: 0;
	bottom: 0;
	left: auto;
	width: var(--rj-detail-panel-width);
	max-width: 100vw;
	z-index: 10080;
	transform: translateX(24px) scale(1.02);
}

.roadview-overlay.detail-left-roadview
{
	position: fixed;
	top: 0;
	right: var(--rj-detail-panel-width, 420px);
	bottom: 0;
	left: 0;
	width: auto;
	min-width: 0;
	max-width: none;
	z-index: 10015;
	transform: translateX(-16px) scale(1.01);
	box-shadow: 20px 0 34px rgba(15, 23, 42, 0.32);
}

.roadview-overlay.detail-left-roadview::after
{
	content: "";
	position: absolute;
	top: 0;
	right: 0;
	bottom: 0;
	width: 18px;
	z-index: 5;
	pointer-events: none;
	background: linear-gradient(to left, rgba(15, 23, 42, 0.26), rgba(15, 23, 42, 0));
}

.roadview-overlay:fullscreen
{
	position: fixed;
	inset: 0;
	width: 100vw;
	height: 100vh;
	min-width: 0;
	max-width: none;
	z-index: 2147483647;
}

.roadview-overlay:-webkit-full-screen
{
	position: fixed;
	inset: 0;
	width: 100vw;
	height: 100vh;
	min-width: 0;
	max-width: none;
	z-index: 2147483647;
}

.roadview-overlay.open
{
	pointer-events: auto;
	opacity: 1;
	transform: translateX(0) scale(1);
}

.roadview-overlay.detail-left-roadview.open
{
	transform: translateX(0) scale(1);
}

