/* ===== PATCH: 매물 등록 기본 페이지 ===== */
.property-register-page
{
	position: absolute;
	inset: var(--global-topbar-height) 0 0 0;
	z-index: 120;
	display: none;
	background: #f4f7fb;
	color: #111827;
	overflow-y: auto;
	padding: 13px 0 114px;
}

body.property-register-page-open .property-register-page
{
	display: block;
}

body.property-register-page-open .sub-topbar,
body.property-register-page-open .sidebar,
body.property-register-page-open .resizer,
body.property-register-page-open .map-wrap
{
	display: none;
}

.property-register-inner
{
	width: min(960px, calc(100vw - 48px));
	margin: 0 auto;
}

.property-register-head
{
	display: flex;
	align-items: center;
	justify-content: flex-end;
	gap: 16px;
	margin-bottom: 13px;
}

.property-register-flag-checks
{
	display: inline-flex;
	align-items: center;
	gap: 30px;
	padding: 13px 0;
	flex: 0 0 auto;
}

.property-register-flag-check
{
	display: inline-flex;
	align-items: center;
	gap: var(--property-register-option-gap);
	color: #111827;
	font-size: var(--property-register-option-font-size);
	font-weight: var(--property-register-option-font-weight);
	line-height: 1;
	letter-spacing: var(--property-register-option-letter-spacing);
	white-space: nowrap;
	cursor: pointer;
	user-select: none;
}

.property-register-flag-check input
{
	width: var(--property-register-info-checkbox-size);
	height: var(--property-register-info-checkbox-size);
	margin: 0;
	accent-color: #2f363d;
	cursor: pointer;
}

.property-register-title
{
	margin: 0;
	font-size: 24px;
	font-weight: 700;
	letter-spacing: -0.35px;
	color: #111827;
	line-height: 1.25;
}

.property-register-top-actions
{
	display: inline-flex;
	align-items: center;
	gap: 10px;
	flex-wrap: wrap;
	padding: 13px 0;
}

.property-register-top-btn
{
	height: 42px;
	padding: 0 18px;
	border: 1px solid #e5e7eb;
	border-radius: 0;
	background: #ffffff;
	color: #111827;
	font-size: 14px;
	font-weight: 700;
	letter-spacing: -0.12px;
	cursor: pointer;
	box-shadow: none;
}

.property-register-card
{
	background: #ffffff;
	border: 1px solid #e5e7eb;
	border-radius: 0;
	box-shadow: none;
	padding: 34px 40px 40px;
	min-height: 520px;
}

.property-register-section-title
{
	margin: 0 0 28px;
	font-size: 22px;
	font-weight: 800;
	letter-spacing: -0.28px;
	color: #111827;
	line-height: 1.3;
}

.property-register-placeholder
{
	display: flex;
	align-items: center;
	justify-content: center;
	min-height: 380px;
	border: 1px dashed #cbd5e1;
	background: #f8fafc;
	color: #64748b;
	font-size: 15px;
	font-weight: 600;
	letter-spacing: -0.12px;
	text-align: center;
	padding: 24px;
}

.property-register-bottom-bar
{
	position: fixed;
	left: 0;
	right: 0;
	bottom: 0;
	z-index: 9995;
	display: none;
	justify-content: center;
	background: rgba(255,255,255,0.96);
	border-top: 1px solid #e5e7eb;
	padding: 18px 0;
	box-shadow: 0 -8px 24px rgba(15, 23, 42, 0.05);
}

body.property-register-page-open .property-register-bottom-bar
{
	display: flex;
}

.property-register-bottom-inner
{
	width: min(960px, calc(100vw - 48px));
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 12px;
}

.property-register-legal-notice
{
	margin: 0;
	flex: 1 1 auto;
	color: #9ca3af;
	font-size: 13px;
	font-weight: 400;
	line-height: 1.55;
	letter-spacing: -0.12px;
	text-align: left;
}

.property-register-bottom-actions
{
	flex: 0 0 auto;
	display: flex;
	align-items: center;
	justify-content: flex-end;
	gap: 12px;
}

.property-register-bottom-btn
{
	height: 52px;
	min-width: 132px;
	padding: 0 22px;
	border-radius: 0;
	font-size: 16px;
	font-weight: 800;
	letter-spacing: -0.18px;
	cursor: pointer;
	box-shadow: none;
}

.property-register-bottom-btn.draft
{
	border: 1px solid #d1d5db;
	background: #ffffff;
	color: #111827;
}

.property-register-bottom-btn.submit
{
	border: 1px solid #1B6FA4;
	background: #1B6FA4;
	color: #ffffff;
}

@media (max-width: 720px)
{
	.property-register-page
	{
		padding-top: 26px;
	}
	.property-register-head
	{
		align-items: flex-start;
		flex-direction: column;
	}
	.property-register-flag-checks
	{
		gap: 18px;
		flex-wrap: wrap;
	}
	.property-register-flag-check
	{
		font-size: var(--property-register-option-font-size);
	}
	.property-register-flag-check input
	{
		width: var(--property-register-info-checkbox-size);
		height: var(--property-register-info-checkbox-size);
	}
	.property-register-card
	{
		padding: 26px 22px 32px;
	}
	.property-register-bottom-inner
	{
		align-items: stretch;
		flex-direction: column;
		justify-content: stretch;
	}
	.property-register-legal-notice
	{
		font-size: 12px;
		line-height: 1.45;
	}
	.property-register-bottom-actions
	{
		width: 100%;
	}
	.property-register-bottom-btn
	{
		flex: 1 1 0;
		min-width: 0;
	}
	.property-direction-pair-field
	{
		grid-template-columns: 1fr;
		gap: 10px;
	}
	.property-direction-base-label
	{
		justify-self: start;
	}
}

/* ===== PATCH: 매물 등록 기본 정보 / 가격 입력 폼 ===== */
