.property-upload-box.has-photo-preview .property-photo-preview-grid
{
	margin-top: 0;
}

.property-photo-preview-grid.is-hidden
{
	display: none;
}

.property-photo-preview-item
{
	position: relative;
	aspect-ratio: 4 / 3;
	border: 1px solid #d7dee8;
	background: #f8fafc;
	overflow: hidden;
	cursor: grab;
	touch-action: none;
	user-select: none;
}

.property-photo-preview-item.is-dragging
{
	opacity: 0.46;
	cursor: grabbing;
}

.property-photo-preview-item.is-drop-target
{
	border-color: #4A7EDC;
	box-shadow: 0 0 0 2px rgba(74, 126, 220, 0.18) inset;
}

.property-photo-drag-ghost
{
	position: fixed;
	left: 0;
	top: 0;
	z-index: 2147483647;
	border: 1px solid rgba(37, 99, 235, 0.45);
	border-radius: 8px;
	background: #ffffff;
	box-shadow: 0 16px 34px rgba(15, 23, 42, 0.28);
	opacity: 0.94;
	overflow: hidden;
	pointer-events: none;
	cursor: grabbing;
	will-change: transform;
}

.property-photo-preview-item img
{
	width: 100%;
	height: 100%;
	object-fit: cover;
	display: block;
}

.property-photo-preview-name
{
	position: absolute;
	left: 0;
	right: 0;
	bottom: 0;
	padding: 6px 8px;
	background: rgba(17, 24, 39, 0.68);
	color: #ffffff;
	font-size: 12px;
	font-weight: 600;
	letter-spacing: -0.1px;
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}

