/* ===== PATCH: 관리자 페이지 - 중개사 신청 관리 ===== */
.admin-page-panel
{
	position: absolute;
	inset: var(--global-topbar-height) 0 0 0;
	z-index: 9990;
	display: none;
	background: #ffffff;
	color: #111827;
	overflow-y: scroll;
	overflow-x: hidden;
	scrollbar-gutter: stable;
	padding: 32px 32px 0;
}

.admin-page-head
{
	position: relative;
	display: flex;
	align-items: center;
	justify-content: center;
	gap: 16px;
	width: 1180px;
	max-width: calc(100vw - 64px);
	margin: 0 auto 52px;
	text-align: center;
}

.admin-page-title
{
	font-size: 34px;
	font-weight: 800;
	letter-spacing: -0.04em;
	line-height: 1.2;
	margin: 0;
	color: #111827;
}

.admin-page-desc
{
	display: none;
}

.admin-refresh-btn
{
	height: 38px;
	padding: 0 16px;
	border: 1px solid #1B6FA4;
	border-radius: 0;
	background: #1B6FA4;
	color: #fff;
	font-size: 14px;
	font-weight: 800;
	cursor: pointer;
	box-shadow: none;
}

.admin-page-head > .admin-refresh-btn
{
	display: none;
}

.admin-application-list
{
	display: flex;
	flex-direction: column;
	gap: 10px;
}

.admin-page-tabs
{
	display: grid;
	grid-template-columns: repeat(6, minmax(0, 1fr));
	width: 1180px;
	max-width: calc(100vw - 64px);
	min-width: 0;
	margin: 0 auto 48px;
	border: 1px solid #e5e7eb;
	border-right: 0;
	background: #ffffff;
	box-sizing: border-box;
}

.admin-page-tab
{
	width: 100%;
	min-width: 0;
	height: 56px;
	border: 0;
	border-right: 1px solid #e5e7eb;
	background: #ffffff;
	color: #111827;
	font: inherit;
	font-size: 15px;
	font-weight: 600;
	letter-spacing: -0.02em;
	cursor: pointer;
	box-shadow: none;
}

.admin-page-tab.active
{
	background: #2563eb;
	color: #ffffff;
	font-weight: 600;
}

.admin-page-tab:focus,
.admin-page-tab:focus-visible
{
	outline: none !important;
	box-shadow: none !important;
	transform: none !important;
}

.admin-page-tab-panel
{
	display: none;
}

.admin-page-tab-panel.active
{
	display: block;
	width: 1180px;
	max-width: calc(100vw - 64px);
	margin: 0 auto 35px;
}

.admin-application-card
{
	display: grid;
	grid-template-columns: minmax(240px, 1.25fr) minmax(320px, 1fr) minmax(140px, 0.65fr) minmax(260px, auto);
	gap: 16px;
	align-items: center;
	padding: 16px;
	border: 1px solid #e5e7eb;
	border-radius: 0;
	background: #fff;
	box-shadow: none;
}

.admin-application-office
{
	font-size: 14px;
	font-weight: 900;
	color: #111827;
	letter-spacing: -0.22px;
	line-height: 1.45;
	margin-bottom: 2px;
}

.admin-application-meta
{
	font-size: 14px;
	font-weight: 700;
	color: #475569;
	line-height: 1.45;
	letter-spacing: -0.1px;
}

.admin-status-badge
{
	display: inline-flex;
	align-items: center;
	justify-content: center;
	min-width: 92px;
	height: 24px;
	padding: 0 8px;
	border-radius: 0;
	font-size: 13px;
	font-weight: 900;
	letter-spacing: -0.1px;
	background: #f1f5f9;
	color: #475569;
}

.admin-status-badge.pending
{
	background: #fff7ed;
	color: #ea580c;
}

.admin-status-badge.active
{
	background: #eff6ff;
	color: #2563eb;
}

.admin-status-badge.rejected
{
	background: #fef2f2;
	color: #dc2626;
}

.admin-application-actions
{
	display: flex;
	align-items: center;
	justify-content: flex-end;
	gap: 8px;
	flex-wrap: wrap;
}

.admin-status-btn
{
	height: 34px;
	padding: 0 12px;
	border: 1px solid #d1d5db;
	border-radius: 999px;
	background: #fff;
	color: #111827;
	font-size: 13px;
	font-weight: 800;
	cursor: pointer;
	box-shadow: none;
}

.admin-status-btn.approve
