	border-color: #2563eb;
	color: #2563eb;
}

.admin-status-btn.pending
{
	border-color: #ea580c;
	color: #ea580c;
}

.admin-status-btn.reject
{
	border-color: #dc2626;
	color: #dc2626;
}

.admin-status-btn.delete
{
	border-color: #6b7280;
	color: #374151;
}

.admin-empty
{
	padding: 28px 0;
	border: 0;
	border-top: 1px solid #e5e7eb;
	border-bottom: 1px solid #e5e7eb;
	background: #fff;
	text-align: center;
	font-size: 15px;
	font-weight: 800;
